/**
 * Basket Brain card.
 *
 * Front: which shop is cheapest today, what it costs, and the approve button.
 * Back:  every item on the list, priced at all three shops.
 *
 * Flip by clicking anywhere that isn't a button.
 */

const CHAINS = ["woolworths", "paknsave", "newworld"];

// Floor for the card body, in px. Both faces share one box, so this just
// stops a short list collapsing the card into a stub.
const DEFAULT_MIN_HEIGHT = 460;

const CHAIN_LABEL = {
  woolworths: "Woolworths",
  paknsave: "PAK'nSAVE",
  newworld: "New World",
};

// Chain logos, embedded as data URIs so the card stays self-contained (no
// extra static path, no load race) and previews in the card picker.
const CHAIN_LOGO = {
  woolworths: "data:image/png;base64,",
  paknsave: "data:image/png;base64,",
  newworld: "data:image/png;base64,",
};

// Short heads for the receipt columns — the full names don't fit.
const CHAIN_SHORT = {
  woolworths: "WW",
  paknsave: "PS",
  newworld: "NW",
};


const norm = (id) => id.split(".").pop().replace(/_/g, "");

const CHAIN_MATCH = {
  woolworths: (n) => n.includes("woolworths"),
  paknsave: (n) => n.includes("paknsave"),
  newworld: (n) => n.includes("newworld"),
};

const money = (n) =>
  typeof n === "number" && !Number.isNaN(n) ? `$${n.toFixed(2)}` : "—";

const STYLES = `
  :host { display: block; }

  .stage { perspective: 1600px; }
  .flipper {
    position: relative;
    transform-style: preserve-3d;
    transition: transform .55s cubic-bezier(.2,.7,.2,1);
  }
  .stage.flipped .flipper { transform: rotateY(180deg); }
  @media (prefers-reduced-motion: reduce) { .flipper { transition: none; } }

  .face {
    background: var(--ha-card-background, var(--card-background-color, #fff));
    border-radius: var(--ha-card-border-radius, 12px);
    border: var(--ha-card-border-width, 1px) solid
            var(--ha-card-border-color, var(--divider-color, #e0e0e0));
    box-shadow: var(--ha-card-box-shadow, none);
    color: var(--primary-text-color);
    overflow: hidden;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    cursor: pointer;
  }
  .face.back {
    position: absolute;
    inset: 0;
    transform: rotateY(180deg);
    display: flex;
    flex-direction: column;
  }

  .head {
    display: flex; align-items: center; justify-content: space-between;
    gap: 8px; padding: 14px 16px 10px;
  }
  .title { font-weight: 600; font-size: 15px; }
  .head-right { display: flex; align-items: center; gap: 8px; }
  .stamp {
    font-size: 11px; color: var(--secondary-text-color);
    font-variant-numeric: tabular-nums; white-space: nowrap;
  }

  .flipbtn {
    font: 600 11px/1 var(--paper-font-body1_-_font-family, inherit);
    letter-spacing: .08em; text-transform: uppercase;
    padding: 6px 8px; border-radius: 7px; cursor: pointer;
    background: none; color: var(--secondary-text-color);
    border: 1px solid var(--divider-color);
  }
  .flipbtn:hover { color: var(--primary-color); border-color: var(--primary-color); }

  .refreshbtn {
    display: inline-flex; align-items: center; justify-content: center;
    padding: 4px; border-radius: 7px; cursor: pointer;
    background: none; color: var(--secondary-text-color);
    border: 1px solid var(--divider-color);
  }
  .refreshbtn ha-icon { --mdc-icon-size: 15px; display: inline-flex; }
  .refreshbtn:hover { color: var(--primary-color); border-color: var(--primary-color); }
  .refreshbtn.busy ha-icon { animation: bb-spin 1s linear infinite; }
  @media (prefers-reduced-motion: reduce) { .refreshbtn.busy ha-icon { animation: none; } }

  .qtyrow { display: flex; align-items: center; gap: 4px; margin-top: 3px; }
  .qbtn {
    display: inline-flex; align-items: center; justify-content: center;
    width: 18px; height: 18px; padding: 0; border-radius: 5px;
    font: 700 12px/1 inherit; cursor: pointer;
    background: none; color: var(--secondary-text-color);
    border: 1px solid var(--divider-color);
  }
  .qbtn:hover:not(:disabled) { color: var(--primary-color); border-color: var(--primary-color); }
  .qbtn:disabled { opacity: .35; cursor: default; }
  .qbtn.del:hover { color: var(--error-color, #a32a22); border-color: var(--error-color, #a32a22); }
  .qval {
    font-size: 11px; font-weight: 600; min-width: 20px; text-align: center;
    color: var(--secondary-text-color); font-variant-numeric: tabular-nums;
  }

  .chip {
    display: inline-flex; align-items: center; gap: 5px;
    font-size: 11px; font-weight: 600; letter-spacing: .04em;
    text-transform: uppercase; padding: 3px 7px; border-radius: 5px;
    white-space: nowrap;
  }
  .chip.ok   { color: var(--success-color, #1f7a4c); background: color-mix(in srgb, var(--success-color, #1f7a4c) 14%, transparent); }
  .chip.warn { color: var(--warning-color, #a8631a); background: color-mix(in srgb, var(--warning-color, #a8631a) 16%, transparent); }
  .chip.bad  { color: var(--error-color,   #a32a22); background: color-mix(in srgb, var(--error-color, #a32a22) 14%, transparent); }
  .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }

  button.btn {
    font: 600 13px/1.2 inherit;
    border: 1px solid var(--divider-color);
    background: none; color: var(--primary-text-color);
    padding: 8px 12px; border-radius: 8px; cursor: pointer;
  }
  button.btn:hover { border-color: var(--primary-color); color: var(--primary-color); }
  button.btn.primary {
    background: var(--primary-color); border-color: var(--primary-color);
    color: var(--text-primary-color, #fff);
  }
  button.btn.primary:hover { opacity: .9; color: var(--text-primary-color, #fff); }
  button.btn.go {
    background: var(--success-color, #1f7a4c);
    border-color: var(--success-color, #1f7a4c);
    color: #fff;
  }
  button.btn.go:hover { opacity: .9; color: #fff; }
  button.btn[disabled] { opacity: .45; cursor: default; }
  button:focus-visible, .flipbtn:focus-visible {
    outline: 2px solid var(--primary-color); outline-offset: 2px;
  }
  .spin {
    display: inline-block; width: 12px; height: 12px;
    margin-right: 6px; vertical-align: -1px;
    border: 2px solid currentColor; border-right-color: transparent;
    border-radius: 50%; animation: bb-spin .6s linear infinite;
  }
  @keyframes bb-spin { to { transform: rotate(360deg); } }
  @media (prefers-reduced-motion: reduce) { .spin { animation: none; } }

  /* ---------- front ---------- */
  .hero { display: flex; align-items: flex-end; gap: 14px; padding: 2px 16px 14px; }
  .hero .money {
    font-size: 40px; font-weight: 600; line-height: 1;
    letter-spacing: -.02em; font-variant-numeric: tabular-nums;
  }
  .hero .who { display: flex; flex-direction: column; gap: 2px; padding-bottom: 3px; }
  .hero .who b { font-size: 14px; }
  .hero .who span { font-size: 12px; color: var(--secondary-text-color); }
  .saving { color: var(--success-color, #1f7a4c); font-weight: 600; }
  .empty { padding: 4px 16px 18px; color: var(--secondary-text-color); font-size: 14px; }

  .rows { border-top: 1px solid var(--divider-color); }
  .row {
    display: grid; grid-template-columns: 4px 1fr auto auto;
    align-items: center; gap: 12px;
    padding: 10px 16px 10px 12px;
    border-bottom: 1px solid var(--divider-color);
  }
  .row .bar { width: 4px; height: 28px; border-radius: 2px; }
  .row .meta { min-width: 0; display: flex; align-items: center; gap: 10px; }
  .row .meta .logo { height: 34px; width: auto; display: block; flex: none; }
  .row .meta small { font-size: 11px; color: var(--secondary-text-color); }
  .row .price { text-align: right; font-variant-numeric: tabular-nums; }
  .row .price b { font-size: 15px; font-weight: 600; }
  .row .price em { display: block; font-style: normal; font-size: 11px; color: var(--secondary-text-color); }
  .row .buildhere { opacity: 0; transition: opacity .15s; font-size: 11px; padding: 5px 8px; }
  .row:hover .buildhere, .row .buildhere:focus-visible { opacity: 1; }
  .row.win { background: color-mix(in srgb, var(--success-color, #1f7a4c) 8%, transparent); }
  .row.dead .meta b, .row.dead .price b { color: var(--secondary-text-color); }
  /* Couldn't reach the shop — dim it, but don't dress it as an error.
     It retries on its own. */
  .row.degraded { opacity: .6; }
  .row.degraded .meta small { font-style: italic; }

  .w-woolworths { background: #007837; }
  .w-paknsave   { background: #ffd400; }
  .w-newworld   { background: #d6231b; }

  .banner {
    display: flex; align-items: center; gap: 10px;
    padding: 10px 16px; font-size: 13px;
    border-bottom: 1px solid var(--divider-color);
    background: color-mix(in srgb, var(--warning-color, #a8631a) 10%, transparent);
  }
  .banner .grow { flex: 1; }
  .foot { display: flex; align-items: center; gap: 8px; padding: 12px 16px; flex-wrap: wrap; }
  .foot .grow { flex: 1; }
  /* The flipper gets an explicit height, so stretch the front to fill it and
     pin the action row to the bottom instead of leaving dead space. */
  .face.front { min-height: 100%; display: flex; flex-direction: column; }
  .face.front .foot { margin-top: auto; }

  /* ---------- back ---------- */
  .back .head { border-bottom: 1px dashed var(--divider-color); }
  .scroll { flex: 1; overflow-y: auto; }
  .cols, .rrow, .rtotal {
    display: grid;
    grid-template-columns: 1fr 56px 56px 56px;
    gap: 6px;
  }
  .cols {
    padding: 8px 16px; font-size: 10px; letter-spacing: .08em;
    text-transform: uppercase; color: var(--secondary-text-color);
  }
  .cols span:not(:first-child),
  .rrow span:not(:first-child),
  .rtotal span:not(:first-child) { text-align: right; }
  .rrow {
    padding: 5px 16px; font-size: 13px; font-variant-numeric: tabular-nums;
  }
  .rrow:nth-child(odd) { background: color-mix(in srgb, var(--primary-text-color) 4%, transparent); }
  .rrow .item { overflow: hidden; min-width: 0; }
  .rrow .item b { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; }
  .rrow .item small { font-size: 11px; color: var(--secondary-text-color); }
  .rrow .item.low-name b { color: var(--warning-color, #a8631a); }
  .rrow .best { color: var(--success-color, #1f7a4c); font-weight: 700; }
  .rrow .gone { color: var(--secondary-text-color); }
  .rtotal {
    padding: 10px 16px; font-weight: 700; font-size: 14px;
    font-variant-numeric: tabular-nums;
    border-top: 1px dashed var(--divider-color);
  }
  .rtotal .cheapest { color: var(--success-color, #1f7a4c); }
  .backfoot {
    display: flex; align-items: center; gap: 8px;
    padding: 12px 16px; font-size: 13px;
    border-top: 1px dashed var(--divider-color);
  }
  .backfoot .grow { flex: 1; }

  /* ---------- needs-your-ok section ---------- */
  .needs-ok { border-bottom: 1px solid var(--divider-color); }
  .needs-ok-head {
    display: flex; align-items: center; gap: 6px;
    padding: 7px 16px; font-size: 10px; font-weight: 700;
    letter-spacing: .08em; text-transform: uppercase;
    color: var(--warning-color, #a8631a);
    background: color-mix(in srgb, var(--warning-color, #a8631a) 8%, transparent);
    border-bottom: 1px solid color-mix(in srgb, var(--warning-color, #a8631a) 20%, transparent);
  }
  .nrow {
    display: flex; align-items: center; gap: 8px;
    padding: 6px 16px;
  }
  .nrow:nth-child(even) { background: color-mix(in srgb, var(--primary-text-color) 3%, transparent); }
  .nrow .nitem { flex: 1; min-width: 0; }
  .nrow .nitem b { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; }
  .nrow .nitem small { font-size: 11px; color: var(--secondary-text-color); }
  button.btn.sm { padding: 4px 8px; font-size: 11px; border-radius: 6px; }
  button.btn.ok-btn {
    background: var(--success-color, #1f7a4c);
    border-color: var(--success-color, #1f7a4c);
    color: #fff; font-size: 11px; padding: 4px 8px; border-radius: 6px;
  }
  button.btn.ok-btn:hover { opacity: .85; color: #fff; }
  button.btn.skip-btn { font-size: 11px; padding: 4px 8px; border-radius: 6px; }

  /* ---------- specials badge ---------- */
  .specials-badge {
    display: inline-flex; align-items: center; gap: 4px;
    font-size: 11px; font-weight: 700; letter-spacing: .04em;
    padding: 3px 8px; border-radius: 5px; cursor: pointer;
    background: color-mix(in srgb, var(--warning-color, #a8631a) 16%, transparent);
    color: var(--warning-color, #a8631a);
    border: 1px solid color-mix(in srgb, var(--warning-color, #a8631a) 30%, transparent);
    white-space: nowrap;
  }
  .specials-badge:hover { opacity: .85; }
  .specials-badge ha-icon { --mdc-icon-size: 15px; }
  .stitle { display: inline-flex; align-items: center; gap: 6px; }
  .stitle ha-icon { --mdc-icon-size: 18px; }

  /* ---------- specials face ---------- */
  .srow {
    display: flex; align-items: center; gap: 8px;
    padding: 8px 16px; font-size: 13px;
    border-bottom: 1px solid var(--divider-color);
  }
  .srow:last-child { border-bottom: none; }
  .srow .sbar { width: 4px; height: 36px; border-radius: 2px; flex: none; }
  .srow .smeta { flex: 1; min-width: 0; }
  .srow .smeta b {
    display: block; overflow: hidden; text-overflow: ellipsis;
    white-space: nowrap; font-size: 13px; font-weight: 500;
  }
  .srow .smeta small { font-size: 11px; color: var(--secondary-text-color); }
  .srow .sprice { text-align: right; font-variant-numeric: tabular-nums; flex: none; margin-right: 8px; }
  .srow .sprice b { font-size: 15px; font-weight: 600; color: var(--success-color, #1f7a4c); }
  .srow .sprice del { display: block; font-size: 11px; color: var(--secondary-text-color); }
  button.btn.add-btn {
    background: var(--success-color, #1f7a4c);
    border-color: var(--success-color, #1f7a4c);
    color: #fff; font-size: 11px; padding: 4px 8px; border-radius: 6px; flex: none;
  }
  button.btn.add-btn:hover { opacity: .85; color: #fff; }
  .specials-empty { padding: 16px; font-size: 14px; color: var(--secondary-text-color); }
`;

class BasketBrainCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    // 0 = front, 1 = back (items receipt), 2 = specials
    this._face = 0;
    this._built = false;
    this._sending = false;
    // Session-local: phrases the user has dismissed from "Needs your OK".
    // Resets on page refresh. Approvals are persisted via service call.
    this._dismissed = new Set();
    // Session-local: specials items the user has added this session.
    this._addedSpecials = new Set();
    // Optimistic hide for items removed via the card — cleared automatically
    // once the sensor data no longer contains the phrase.
    this._removedItems = new Set();
  }

  static getStubConfig() {
    return { type: "custom:basket-brain-card" };
  }

  static getConfigElement() {
    return document.createElement("basket-brain-card-editor");
  }

  setConfig(config = {}) {
    // Entities are discovered, not configured. The config is only here for
    // overrides, for the odd case where discovery picks the wrong one.
    this._config = {
      ...config,
      min_height: Number(config.min_height) || DEFAULT_MIN_HEIGHT,
      totals: config.totals || {},
      items: config.items || {},
      login: config.login || {},
    };
    this._ids = null;
    this._face = 0;
    this._built = false;

    // Nothing can throw past this point. Any exception out of setConfig
    // as a bad config swallows the error and shows bare "Configuration error"
    // card.
    this._safeRender();
  }

  set hass(hass) {
    this._hass = hass;
    // HA fires this on every state change anywhere in the instance. Only
    // re-render when something the card actually shows has changed — otherwise
    // the constant innerHTML rebuild resets the list's scroll to the top.
    const sig = this._stateSignature();
    if (this._built && sig !== "" && sig === this._lastSig) return;
    this._lastSig = sig;
    this._safeRender();
  }

  /** A cheap fingerprint of just the entities this card renders from. */
  _stateSignature() {
    const ids = this._entities();
    if (!ids) return "";
    const parts = [];
    const push = (id) => {
      const s = this._state(id);
      parts.push(`${id}:${s ? `${s.state}@${s.last_updated}` : "-"}`);
    };
    push(ids.shopping_list);
    push(ids.pending_cart);
    push(ids.specials_alerts);
    for (const c of CHAINS) {
      push(ids.totals[c]);
      push(ids.items[c]);
      push(ids.login[c]);
    }
    return parts.join("|");
  }

  connectedCallback() {
    this._safeRender();
  }

  /** Render, but never let a failure escape into HA's config handling. */
  _safeRender() {
    try {
      this._render();
    } catch (err) {
      console.error("[basket-brain-card] render failed:", err);
      this.shadowRoot.innerHTML =
        `<style>${STYLES}</style>` +
        `<div class="face"><div class="head">` +
        `<span class="title">Basket Brain</span></div>` +
        `<div class="empty">Card failed to render: ${err.message}</div></div>`;
    }
  }

  getCardSize() {
    return 6;
  }

  // ---------------------------------------------------------------
  // Reading state
  // ---------------------------------------------------------------

  _state(entityId) {
    return entityId ? this._hass?.states?.[entityId] : undefined;
  }

  /**
   * Find every entity the basket_brain integration owns and work out what
   * each one is. Config overrides win; discovery fills in the rest.
   */
  _entities() {
    if (this._ids) return this._ids;
    if (!this._hass?.entities) return null;

    const mine = Object.keys(this._hass.entities).filter(
      (id) => this._hass.entities[id].platform === "basket_brain"
    );

    const ids = {
      totals: { ...this._config.totals },
      items: { ...this._config.items },
      login: { ...this._config.login },
      shopping_list: this._config.shopping_list,
      pending_cart: this._config.pending_cart,
      specials_alerts: this._config.specials_alerts,
    };

    for (const id of mine) {
      const n = norm(id);
      const chain = CHAINS.find((c) => CHAIN_MATCH[c](n));

      if (id.startsWith("binary_sensor.") && chain) {
        ids.login[chain] ??= id;
      } else if (n.includes("baskettotal") && chain) {
        ids.totals[chain] ??= id;
      } else if (n.includes("items") && chain) {
        ids.items[chain] ??= id;
      } else if (n.includes("shoppinglist")) {
        ids.shopping_list ??= id;
      } else if (n.includes("pendingcart")) {
        ids.pending_cart ??= id;
      } else if (n.includes("specialsalerts")) {
        ids.specials_alerts ??= id;
      }
    }

    // Only cache once the entity list has actually turned up.
    if (mine.length) this._ids = ids;
    return ids;
  }

  /** Chains the integration actually set up — the rest were never enabled.
   *
   * With nothing found (the card picker's preview, or before HA has loaded
   * the entities) fall back to all three, so the card previews as an empty
   * board rather than nothing at all.
   */
  _activeChains() {
    const ids = this._entities();
    if (!ids) return CHAINS;
    const live = CHAINS.filter((c) => this._state(ids.totals[c]));
    return live.length ? live : CHAINS;
  }

  _total(chain) {
    const s = this._state(this._entities()?.totals[chain]);
    const n = s ? Number(s.state) : NaN;
    return Number.isFinite(n) ? n : null;
  }

  /** Cheapest chain, the runner-up gap, and the dearest — or nulls. */
  _verdict() {
    const priced = this._activeChains()
      .map((chain) => ({ chain, total: this._total(chain) }))
      .filter((r) => r.total !== null)
      .sort((a, b) => a.total - b.total);

    if (!priced.length) return { best: null, dearest: null, saving: null };
    const best = priced[0];
    const dearest = priced[priced.length - 1];
    const saving = priced.length > 1 ? dearest.total - best.total : null;
    return { best, dearest, saving };
  }

  _pending() {
    const s = this._state(this._entities()?.pending_cart);
    if (!s || s.state === "none" || s.state === "unavailable") return null;
    return {
      chain: s.state,
      total: s.attributes.total_nzd,
      count: s.attributes.item_count ?? 0,
      outOfStock: s.attributes.out_of_stock || [],
    };
  }

  /** Signed-in state: true, false, or null when unknown (no sensor / unavailable). */
  _signedIn(chain) {
    const s = this._state(this._entities()?.login[chain]);
    if (!s || s.state === "unavailable" || s.state === "unknown") return null;
    return s.state === "on";
  }

  _loginTrouble() {
    return this._activeChains().filter((c) => this._signedIn(c) === false);
  }

  /**
   * Chains that dropped out of the last update. Their prices are stale or
   * missing, but the integration retries every tick — so this is a "hang on"
   * state, not a "something is broken" state.
   */
  _degraded() {
    const s = this._state(this._entities()?.shopping_list);
    return new Set(s?.attributes?.degraded_chains || []);
  }

  /** Items priced at one chain, from that chain's items sensor. */
  _itemCount(chain) {
    const s = this._state(this._entities()?.items[chain]);
    const n = s ? Number(s.state) : NaN;
    return Number.isFinite(n) ? n : null;
  }

  _listItems() {
    const s = this._state(this._entities()?.shopping_list);
    return s?.attributes?.items || [];
  }

  /** The configured primary chain, or null when unknown. */
  _primaryChain() {
    const s = this._state(this._entities()?.shopping_list);
    return s?.attributes?.primary_chain || null;
  }

  _specialsCount() {
    const s = this._state(this._entities()?.specials_alerts);
    const n = s ? Number(s.state) : NaN;
    return Number.isFinite(n) ? n : 0;
  }

  _specialsItems() {
    const s = this._state(this._entities()?.specials_alerts);
    return s?.attributes?.items || [];
  }

  // ---------------------------------------------------------------
  // Actions
  // ---------------------------------------------------------------

  _call(service, data = {}) {
    if (!this._hass) return Promise.resolve();
    return this._hass.callService("basket_brain", service, data);
  }

  /** Approve button — a spinner while the cart is being sent. */
  _approveBtn() {
    return this._sending
      ? `<button class="btn go" disabled><span class="spin"></span>Sending…</button>`
      : `<button class="btn go" data-service="approve_cart">Approve</button>`;
  }

  /**
   * Navigate between faces.
   * @param {number|null} targetFace - 0=front, 1=back(items), 2=specials.
   *   Null cycles: front→back→front (specials is only reachable by badge/button).
   */
  _flip(targetFace = null) {
    if (targetFace !== null) {
      this._face = targetFace;
    } else {
      // Generic click: toggle between front and back only.
      this._face = this._face === 0 ? 1 : 0;
    }
    this._render();
  }

  // ---------------------------------------------------------------
  // Helpers — confidence / resolved names
  // ---------------------------------------------------------------

  /**
   * Return the best available resolved name for an item row.
   * Prefers the cheapest chain's name, then any non-null name, then null.
   */
  _bestName(row, chains) {
    const priced = chains
      .filter((c) => typeof row[c] === "number")
      .sort((a, b) => row[a] - row[b]);
    for (const c of priced) {
      const n = row[`${c}_name`];
      if (n) return n;
    }
    // No priced chain with a name — try anything
    for (const c of chains) {
      const n = row[`${c}_name`];
      if (n) return n;
    }
    return null;
  }

  /**
   * Return item rows that have at least one low-confidence resolution
   * on an active chain, excluding session-dismissed phrases.
   */
  _needsOkItems(items, chains) {
    return items.filter(
      (row) =>
        !this._dismissed.has(row.item) &&
        chains.some(
          (c) =>
            row[`${c}_confidence`] === "low" && typeof row[c] === "number"
        )
    );
  }

  /**
   * Render the "Needs your OK" section for low-confidence resolutions.
   */
  _needsOkSection(items, chains) {
    const pending = this._needsOkItems(items, chains);
    if (!pending.length) return "";

    const rows = pending
      .map((row) => {
        const name = this._bestName(row, chains) || row.item;
        const showPhrase = name !== row.item;
        const lowChains = chains.filter(
          (c) =>
            row[`${c}_confidence`] === "low" && typeof row[c] === "number"
        );
        return `
          <div class="nrow">
            <span class="nitem">
              <b>⚠ ${name}</b>
              ${showPhrase ? `<small>${row.item}</small>` : ""}
            </span>
            <button class="btn ok-btn"
                    data-service="approve_resolution"
                    data-phrase="${row.item}"
                    data-low-chains="${lowChains.join(",")}">OK</button>
            <button class="btn skip-btn"
                    data-dismiss="${row.item}">Skip</button>
          </div>`;
      })
      .join("");

    return `
      <div class="needs-ok">
        <div class="needs-ok-head">
          Needs your OK — ${pending.length} item${pending.length !== 1 ? "s" : ""}
        </div>
        ${rows}
      </div>`;
  }

  // ---------------------------------------------------------------
  // Rendering
  // ---------------------------------------------------------------

  _render() {
    // Renders with no hass too — that's the state the card picker previews in,
    // and every read below tolerates a missing entity.
    if (!this._config) return;

    if (!this._built) {
      this.shadowRoot.innerHTML = `
        <style>${STYLES}</style>
        <div class="stage">
          <div class="flipper">
            <div class="face front"></div>
            <div class="face back"></div>
          </div>
        </div>`;
      const stage = this.shadowRoot.querySelector(".stage");
      // Click anywhere that isn't a control to flip.
      // Specials face (2) goes back to front; others cycle front↔back.
      stage.addEventListener("click", (ev) => {
        if (ev.target.closest("button")) return;
        if (this._face === 2) {
          this._flip(0);
        } else {
          this._flip();
        }
      });
      this._built = true;
    }

    const stage = this.shadowRoot.querySelector(".stage");
    stage?.classList.toggle("flipped", this._face !== 0);

    // Rebuilding innerHTML drops the scroll container's position — capture it
    // first so a background refresh doesn't yank the user back to the top.
    const back = this.shadowRoot.querySelector(".back");
    const prevScroll = back.querySelector(".scroll")?.scrollTop || 0;

    this.shadowRoot.querySelector(".front").innerHTML = this._front();
    back.innerHTML = this._face === 2 ? this._specials() : this._back();

    const scroll = back.querySelector(".scroll");
    if (scroll) scroll.scrollTop = prevScroll;

    this._wire();
    this._sizeToTallestFace();
  }

  /** Both faces occupy the same box, so the card takes the taller one. */
  _sizeToTallestFace() {
    const flipper = this.shadowRoot.querySelector(".flipper");
    const front = this.shadowRoot.querySelector(".front");
    const back = this.shadowRoot.querySelector(".back");
    if (!flipper) return;
    // Collapsing to re-measure briefly shrinks the page, which the browser
    // answers by scrolling up. Snapshot the page scroll and put it straight
    // back so the measurement is invisible to the user.
    const scroller = document.scrollingElement || document.documentElement;
    const y = scroller ? scroller.scrollTop : 0;
    flipper.style.height = "";
    const h = Math.max(
      front.offsetHeight,
      back.scrollHeight,
      this._config?.min_height || 0
    );
    flipper.style.height = `${h}px`;
    if (scroller) scroller.scrollTop = y;
  }

  _wire() {
    const root = this.shadowRoot;

    // Generic flip (card-body click targets)
    root.querySelectorAll("[data-flip]").forEach((el) =>
      el.addEventListener("click", (ev) => {
        ev.stopPropagation();
        this._flip();
      })
    );

    // Manual refresh — asks HA to update the shopping list sensor, which
    // triggers a full coordinator cycle. The spin is an acknowledgement of
    // the click, not a progress bar; new prices land when the cycle does.
    root.querySelectorAll("[data-refresh]").forEach((el) =>
      el.addEventListener("click", async (ev) => {
        ev.stopPropagation();
        const id = this._entities()?.shopping_list;
        if (!id || el.classList.contains("busy")) return;
        el.classList.add("busy");
        try {
          await this._hass.callService("homeassistant", "update_entity", {
            entity_id: id,
          });
        } finally {
          setTimeout(() => el.classList.remove("busy"), 3000);
        }
      })
    );

    // Explicit face navigation (badges, buttons)
    root.querySelectorAll("[data-goto]").forEach((el) =>
      el.addEventListener("click", (ev) => {
        ev.stopPropagation();
        this._flip(parseInt(el.dataset.goto, 10));
      })
    );

    root.querySelectorAll("[data-service]").forEach((el) =>
      el.addEventListener("click", async (ev) => {
        ev.stopPropagation();
        const chain = el.dataset.chain;
        const service = el.dataset.service;
        // Approve takes a few seconds (it builds the online cart) — show a
        // spinner until the service call resolves.
        if (service === "approve_cart") {
          this._sending = true;
          this._render();
          try {
            await this._call(service);
          } finally {
            this._sending = false;
            this._render();
          }
          return;
        }
        // approve_resolution: call once per low-confidence chain, then
        // add the phrase to the dismissed set so it leaves the section.
        if (service === "approve_resolution") {
          const phrase = el.dataset.phrase;
          const lowChains = (el.dataset.lowChains || "").split(",").filter(Boolean);
          for (const c of lowChains) {
            this._call("approve_resolution", { phrase, chain: c });
          }
          this._dismissed.add(phrase);
          this._render();
          return;
        }
        this._call(service, chain ? { chain } : {});
      })
    );

    // Quantity stepper — persists via the integration; totals re-push
    // immediately (no refetch), so the card updates within a beat.
    root.querySelectorAll("[data-qty-adj]").forEach((el) =>
      el.addEventListener("click", (ev) => {
        ev.stopPropagation();
        const phrase = el.dataset.phrase;
        const next = Math.min(
          99,
          Math.max(1, parseInt(el.dataset.current, 10) + parseInt(el.dataset.qtyAdj, 10))
        );
        if (String(next) === el.dataset.current) return;
        this._call("set_quantity", { phrase, quantity: next });
      })
    );

    // Remove from the HA shopping list. The row hides straight away; the
    // next cycle (triggered by the todo change) makes it real.
    root.querySelectorAll("[data-remove]").forEach((el) =>
      el.addEventListener("click", async (ev) => {
        ev.stopPropagation();
        const phrase = el.dataset.remove;
        const todoEntity = this._config.todo_entity || "todo.shopping_list";
        this._removedItems.add(phrase);
        this._render();
        try {
          await this._hass.callService("todo", "remove_item", {
            entity_id: todoEntity,
            item: phrase,
          });
        } catch (err) {
          console.error("[basket-brain-card] remove failed:", err);
          this._removedItems.delete(phrase);
          this._render();
        }
      })
    );

    // Session-local dismiss ("Skip") — no service call needed.
    root.querySelectorAll("[data-dismiss]").forEach((el) =>
      el.addEventListener("click", (ev) => {
        ev.stopPropagation();
        this._dismissed.add(el.dataset.dismiss);
        this._render();
      })
    );

    // Add specials item to the HA shopping list + pin the exact product.
    root.querySelectorAll("[data-add-special]").forEach((el) =>
      el.addEventListener("click", async (ev) => {
        ev.stopPropagation();
        const name = el.dataset.name;
        const chain = el.dataset.chain;
        const productId = el.dataset.productId;
        const todoEntity = this._config.todo_entity || "todo.shopping_list";

        el.disabled = true;
        try {
          // 1. Add item to the HA shopping list (opt-in only; nothing auto-adds)
          await this._hass.callService("todo", "add_item", {
            entity_id: todoEntity,
            item: name,
          });
          // 2. Pin the exact on-special product so the resolver buys this one
          if (productId && chain) {
            await this._call("pin_alias", {
              phrase: name,
              chain,
              product_id: productId,
            });
          }
          this._addedSpecials.add(`${name}:${chain}`);
          this._render();
        } catch (err) {
          console.error("[basket-brain-card] add-special failed:", err);
          el.disabled = false;
        }
      })
    );
  }

  _loginChip() {
    const trouble = this._loginTrouble();
    if (!this._activeChains().some((c) => this._signedIn(c) !== null)) return "";
    if (!trouble.length) {
      return `<span class="chip ok"><span class="dot"></span>Signed in</span>`;
    }
    const names = trouble.map((c) => CHAIN_LABEL[c]).join(", ");
    return `<span class="chip bad"><span class="dot"></span>${names} signed out</span>`;
  }

  _front() {
    const { best, dearest, saving } = this._verdict();
    const pending = this._pending();

    const hero = best
      ? `<div class="hero">
           <span class="money">${money(best.total)}</span>
           <span class="who">
             <b>${CHAIN_LABEL[best.chain]}</b>
             <span>${
               saving
                 ? `<span class="saving">saves ${money(saving)}</span> vs ${CHAIN_LABEL[dearest.chain]}`
                 : "the only shop with prices"
             }</span>
           </span>
         </div>`
      : `<div class="empty">No prices yet. The next refresh will fill this in.</div>`;

    const degraded = this._degraded();
    const rows = this._activeChains()
      .map((chain) => {
        const total = this._total(chain);
        const isBest = best && chain === best.chain;
        const gap =
          best && total !== null && !isBest ? `+${money(total - best.total)}` : "";
        const priced = this._itemCount(chain);
        const listed = this._listItems().length;
        const sub =
          priced === null ? "not priced" : `${priced} of ${listed} items`;
        const signedOut = this._signedIn(chain) === false;
        const isDegraded = degraded.has(chain);
        // Degraded outranks signed-out: if we couldn't reach the shop at all,
        // "needs reauth" would send you off fixing the wrong thing.
        const note = isDegraded
          ? `couldn't reach ${CHAIN_LABEL[chain]} — still trying`
          : signedOut
            ? "signed out — needs reauth"
            : sub;

        return `
          <div class="row ${isBest ? "win" : ""} ${
            total === null ? "dead" : ""
          } ${isDegraded ? "degraded" : ""}">
            <span class="bar w-${chain}"></span>
            <span class="meta">
              <img class="logo" src="${CHAIN_LOGO[chain]}" alt="${CHAIN_LABEL[chain]}" />
              <small>${note}</small>
            </span>
            <span class="price">
              <b>${money(total)}</b>
              <em>${isBest ? "cheapest" : gap}</em>
            </span>
            <button class="btn buildhere" data-service="build_cart" data-chain="${chain}"
                    ${total === null ? "disabled" : ""}>SHOP</button>
          </div>`;
      })
      .join("");

    const banner = pending
      ? `<div class="banner">
           <span class="chip warn"><span class="dot"></span>Ready</span>
           <span class="grow">${pending.count} items at ${CHAIN_LABEL[pending.chain]} · ${money(pending.total)}${
             pending.outOfStock.length
               ? ` · ${pending.outOfStock.length} skipped, out of stock`
               : ""
           }</span>
           ${this._approveBtn()}
         </div>`
      : "";

    const specialsCount = this._specialsCount();
    const specialsBadge = specialsCount > 0
      ? `<button class="specials-badge" data-goto="2" aria-label="View specials on your usual products">
           <ha-icon icon="mdi:sale"></ha-icon>${specialsCount} on special
         </button>`
      : "";

    return `
      <div class="head">
        <span class="title">Basket Brain</span>
        <span class="head-right">
          ${specialsBadge}
          <button class="refreshbtn" data-refresh aria-label="Refresh prices now" title="Refresh prices now">
            <ha-icon icon="mdi:refresh"></ha-icon>
          </button>
          <button class="flipbtn" data-flip aria-label="Show every item">Items ›</button>
        </span>
      </div>
      ${hero}
      <div class="rows">${rows}</div>
      ${banner}
      <div class="foot">
        <button class="btn primary" data-service="build_cheapest_cart" ${
          best ? "" : "disabled"
        }>SHOP CHEAPEST</button>
        <span class="grow"></span>
        ${this._loginChip()}
      </div>`;
  }

  _specials() {
    const specials = this._specialsItems();

    const body = specials.length === 0
      ? `<div class="specials-empty">No usual products are on special right now.</div>`
      : specials
          .map((s) => {
            const key = `${s.name}:${s.chain}`;
            const added = this._addedSpecials.has(key);
            const saving = s.saving ? ` · saves ${money(s.saving)}` : "";
            return `
              <div class="srow">
                <span class="sbar w-${s.chain}"></span>
                <span class="smeta">
                  <b>${s.name || "—"}</b>
                  <small>${CHAIN_LABEL[s.chain] || s.chain}${saving}</small>
                </span>
                <span class="sprice">
                  <b>${money(s.now_price)}</b>
                  ${s.was_price ? `<del>${money(s.was_price)}</del>` : ""}
                </span>
                <button class="btn add-btn"
                        data-add-special
                        data-name="${(s.name || "").replace(/"/g, "&quot;")}"
                        data-chain="${s.chain}"
                        data-product-id="${s.product_id || ""}"
                        ${added ? "disabled" : ""}>${added ? "✓ Added" : "+ Add"}</button>
              </div>`;
          })
          .join("");

    const count = specials.length;
    return `
      <div class="head">
        <span class="title stitle"><ha-icon icon="mdi:sale"></ha-icon>On special${count ? ` · ${count}` : ""}</span>
        <button class="flipbtn" data-goto="0" aria-label="Back to totals">‹ Back</button>
      </div>
      <div class="scroll">${body}</div>
      <div class="backfoot">
        <span class="grow">Tap + Add to add to your shopping list</span>
      </div>`;
  }

  _back() {
    const chains = this._activeChains();
    let items = this._listItems();
    // Optimistically hide rows removed via the card until the next cycle
    // confirms; drop stale entries once the sensor has caught up.
    this._removedItems = new Set(
      [...this._removedItems].filter((p) => items.some((r) => r.item === p))
    );
    items = items.filter((r) => !this._removedItems.has(r.item));
    const { best } = this._verdict();
    const pending = this._pending();

    const needsOk = this._needsOkSection(items, chains);

    const cols = `
      <div class="cols">
        <span>Item</span>
        ${chains.map((c) => `<span>${CHAIN_SHORT[c]}</span>`).join("")}
      </div>`;

    const rows =
      items.length === 0
        ? `<div class="empty">Nothing on the shopping list.</div>`
        : items
            .map((row) => {
              const prices = chains
                .map((c) => (typeof row[c] === "number" ? row[c] : null))
                .filter((p) => p !== null);
              const cheapest = prices.length ? Math.min(...prices) : null;

              // Are all priced chains resolving to the same product name?
              const pricedChains = chains.filter(
                (c) => typeof row[c] === "number"
              );
              const resolvedNames = pricedChains
                .map((c) => row[`${c}_name`])
                .filter(Boolean);
              const allSame =
                resolvedNames.length > 0 &&
                resolvedNames.every((n) => n === resolvedNames[0]);

              const qty = Math.max(1, row.quantity || 1);
              const cells = chains
                .map((c) => {
                  const p = row[c];
                  if (typeof p !== "number") {
                    return `<span class="gone">—</span>`;
                  }
                  const isBest = p === cheapest;
                  // When chains resolved different products, tooltip shows the
                  // actual product this chain picked.
                  const chainName = !allSame ? row[`${c}_name`] : null;
                  const titleAttr = chainName
                    ? ` title="${chainName}"`
                    : "";
                  // Cells show the line total (unit × qty) so the columns
                  // still sum to the chain totals underneath.
                  return `<span class="${isBest ? "best" : ""}"${titleAttr}>${(p * qty).toFixed(2)}</span>`;
                })
                .join("");

              // Mark as low-confidence if any active chain resolved that way.
              const isLow = chains.some(
                (c) =>
                  row[`${c}_confidence`] === "low" &&
                  typeof row[c] === "number"
              );
              // Item column shows the primary chain's product name (falling
              // back to the best-priced chain's name, then the raw phrase).
              // The spoken/typed phrase rides along as a subtitle when it
              // differs. Per-chain differences still surface as price tooltips.
              const primary = this._primaryChain();
              const primaryName =
                primary && chains.includes(primary)
                  ? row[`${primary}_name`]
                  : null;
              const shownName =
                primaryName || this._bestName(row, chains) || row.item;
              const nameEl =
                `<b title="${row.item}">${shownName}</b>` +
                (shownName !== row.item ? `<small>${row.item}</small>` : "");

              const phraseAttr = row.item.replace(/"/g, "&quot;");
              const qtyCtl = `
                <span class="qtyrow">
                  <button class="qbtn" data-qty-adj="-1" data-phrase="${phraseAttr}"
                          data-current="${qty}" aria-label="One fewer"
                          ${qty <= 1 ? "disabled" : ""}>−</button>
                  <span class="qval">×${qty}</span>
                  <button class="qbtn" data-qty-adj="1" data-phrase="${phraseAttr}"
                          data-current="${qty}" aria-label="One more">+</button>
                  <button class="qbtn del" data-remove="${phraseAttr}"
                          aria-label="Remove from list">✕</button>
                </span>`;

              return `<div class="rrow">
                <span class="item${isLow ? " low-name" : ""}">${nameEl}${qtyCtl}</span>
                ${cells}
              </div>`;
            })
            .join("");

    const totals = chains
      .map((c) => {
        const t = this._total(c);
        const isBest = best && c === best.chain;
        return `<span class="${isBest ? "cheapest" : ""}">${
          t === null ? "—" : t.toFixed(2)
        }</span>`;
      })
      .join("");

    const foot = pending
      ? `<div class="backfoot">
           <span class="chip warn"><span class="dot"></span>Ready</span>
           <span class="grow">${CHAIN_LABEL[pending.chain]} · ${money(pending.total)}</span>
           ${this._approveBtn()}
         </div>`
      : `<div class="backfoot">
           <button class="btn primary" data-service="build_cheapest_cart" ${
             best ? "" : "disabled"
           }>SHOP CHEAPEST</button>
           <span class="grow"></span>
           ${this._loginChip()}
         </div>`;

    return `
      <div class="head">
        <span class="title">${items.length} items · every shop</span>
        <span class="head-right">
          <button class="flipbtn" data-flip aria-label="Back to the totals">‹ Totals</button>
        </span>
      </div>
      ${needsOk}
      ${cols}
      <div class="scroll">${rows}</div>
      <div class="rtotal"><span>TOTAL</span>${totals}</div>
      ${foot}`;
  }
}

customElements.define("basket-brain-card", BasketBrainCard);

/**
 * Visual editor. Entities are auto-discovered, so the only thing worth
 * exposing is how tall the card sits.
 */
class BasketBrainCardEditor extends HTMLElement {
  constructor() {
    super();
    this._config = {};
  }

  static get SCHEMA() {
    return [
      {
        name: "min_height",
        selector: {
          number: { min: 260, max: 900, step: 10, mode: "slider" },
        },
      },
    ];
  }

  setConfig(config) {
    this._config = { ...config };
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    if (this._form) this._form.hass = hass;
  }

  _render() {
    if (this._form) {
      this._form.data = this._data();
      return;
    }

    const note = document.createElement("div");
    note.style.cssText =
      "font-size:13px;color:var(--secondary-text-color);margin-bottom:12px;";
    note.textContent =
      "Basket Brain finds its own entities — nothing to pick here. " +
      "Set how tall the card sits on your dashboard.";

    this._form = document.createElement("ha-form");
    this._form.hass = this._hass;
    this._form.schema = BasketBrainCardEditor.SCHEMA;
    this._form.data = this._data();
    this._form.computeLabel = () => "Card height (px)";
    this._form.addEventListener("value-changed", (ev) => {
      ev.stopPropagation();
      const config = { ...this._config, ...ev.detail.value };
      this._config = config;
      this.dispatchEvent(
        new CustomEvent("config-changed", {
          detail: { config },
          bubbles: true,
          composed: true,
        })
      );
    });

    this.replaceChildren(note, this._form);
  }

  _data() {
    return {
      min_height: Number(this._config.min_height) || DEFAULT_MIN_HEIGHT,
    };
  }
}

customElements.define("basket-brain-card-editor", BasketBrainCardEditor);

window.customCards = window.customCards || [];
window.customCards.push({
  type: "basket-brain-card",
  name: "Basket Brain",
  description:
    "Which supermarket's cheapest today, and what every item costs at all three.",
  preview: true,
});

console.info("%c BASKET-BRAIN-CARD ", "background:#007837;color:#fff", "loaded");
